$cases = @(
    @{ name='probe-real-cwd';   cmd='rm --no-preserve-root'; cwd='C:\Users\UserX\.zcode\workspace\default'; expect=2 }
    @{ name='probe-proj-cwd';   cmd='rm --no-preserve-root'; cwd='C:\proj'; expect=2 }
    @{ name='probe-win-rm-ws';  cmd='rm -rf C:\Windows\System32'; cwd='C:\Users\UserX\.zcode\workspace\default'; expect=2 }
)
foreach ($c in $cases) {
    if (Test-Path "$env:USERPROFILE\.zcode\hooks\state") { Remove-Item "$env:USERPROFILE\.zcode\hooks\state" -Recurse -Force }
    $payload = @{ tool_name = 'Bash'; tool_input = @{ command = $c.cmd }; cwd = $c.cwd } | ConvertTo-Json -Depth 5
    $errFile = "$env:TEMP\dg-err.txt"
    $null = $payload | & $pwsh -NoProfile -ExecutionPolicy Bypass -File $guard 2> $errFile
    '{0,-16} expect={1} got={2}' -f $c.name, $c.expect, $LASTEXITCODE
    if ($LASTEXITCODE -ne $c.expect) {
        'STDERR:'; Get-Content $errFile | Select-Object -First 5
    }
}
